-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8706, 19, 'Landesantidiskriminierungsgesetz mit Rechtsschutz gegen Diskriminierung durch Behörden einführen oder stärken (Land)', 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'offen', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'land', null, true, 'blind'),
  (8707, 19, 'Landesantidiskriminierungsgesetz aufheben oder einschränken (Land)', 'Landesrechtlich ohne Weiteres möglich, verringert aber den Rechtsschutz gegen Diskriminierung durch Behörden, statt ihn zu stärken; die bestehende Ombudsstelle bearbeitet jährlich hunderte Anfragen.', 'offen', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'land', null, true, 'blind'),
  (8708, 19, 'Unabhängige Beschwerdestellen gegen Diskriminierung in Schulen, Hochschulen und öffentlichen Einrichtungen (Land)', 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'offen', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'land', null, true, 'blind'),
  (8709, 19, 'Antidiskriminierungs-Fortbildungen für Beschäftigte in Verwaltung, Polizei, Schule und Gesundheit (Land)', 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'gemischt', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'land', null, true, 'blind'),
  (8710, 19, 'Anlasslose Polizeikontrollbefugnisse einschränken und Polizeirecht gegen Racial Profiling absichern (Land)', 'Setzt an Befugnissen an, die diskriminierende Kontrollen ermöglichen, und ist im Landespolizeirecht regelbar; Studien zur Wirkung einer Abschaffung solcher Befugnisse fehlen, Sicherheitsfolgen sind umstritten.', 'offen', null, 'land', null, true, 'blind'),
  (8711, 19, 'Kontrollquittungen bei polizeilichen Kontrollen einführen (Land)', 'Dokumentation macht Kontrollen überprüfbar; in Fuenlabrada sanken Kontrollzahl und Überrepräsentation marokkanischer Personen bei höherer Trefferquote. Belege stammen aus einem Pilotort und von Befürwortern.', 'offen', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'land', null, true, 'blind'),
  (8712, 19, 'Diskriminierungskritische Prüfung, Diversity-Strategien und Ansprechstellen in Verwaltung und Polizei (Land)', 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8713, 19, 'Antidiskriminierungs- und Betroffenenberatung ausbauen und dauerhaft finanzieren (Land)', 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'offen', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'land', null, true, 'blind'),
  (8714, 19, 'Landesprogramme, Aktionspläne und Projektförderung gegen Rassismus, Antisemitismus und Queerfeindlichkeit (Land)', 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'gemischt', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'land', null, true, 'blind'),
  (8715, 19, 'Schulische Bildungs- und Präventionsprogramme gegen Rassismus, Antisemitismus und Queerfeindlichkeit (Land)', 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'gemischt', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'land', null, true, 'blind'),
  (8716, 19, 'Begegnungs- und Dialogprogramme zwischen Gruppen fördern (Land)', 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; vorregistrierte Experimente finden aber kleinere, oft auf die Beteiligten begrenzte Effekte. Die Reichweite einzelner Projekte ist gering.', 'gemischt', 'https://forrt.org/open-social-psychology/chapter12.html', 'land', null, true, 'blind'),
  (8717, 19, 'Erinnerungs- und Sichtbarkeitsprojekte wie Gedenkorte, Museen und Kulturförderung (Land)', 'Kann Wissen und Sichtbarkeit von Minderheiten stärken, wirkt auf verbreitete Einstellungen aber nur mittelbar; die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8718, 19, 'Systematische Datenerhebung und Dunkelfeldstudien zu Diskriminierung (Land)', 'Verbessert die Grundlage für gezielte Maßnahmen, verändert Einstellungen oder Benachteiligung aber nicht selbst.', 'offen', null, 'land', null, true, 'blind'),
  (8719, 19, 'Landesförderung für Antidiskriminierungsprojekte, Meldestellen und politische Bildung einstellen (Land)', 'Haushaltsrechtlich leicht umsetzbar, schwächt aber Präventions-, Melde- und Unterstützungsangebote; ein Beitrag zum Abbau rassistischer Zuschreibungen ist nicht erkennbar.', 'offen', null, 'land', null, true, 'blind'),
  (8720, 19, 'Antidiskriminierungsbeauftragte und Diversity-Schulungen in der Landesverwaltung abschaffen (Land)', 'Spart Mittel und ist leicht umsetzbar, entfernt aber Anlaufstellen und Sensibilisierung gegen Diskriminierung durch Behörden; zum Ziel trägt es nicht bei.', 'offen', null, 'land', null, true, 'blind'),
  (8721, 19, 'Queere Bildungs-, Akzeptanz- und Sichtbarkeitsarbeit in Schulen und Landesförderung einschränken (Land)', 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'offen', null, 'land', null, true, 'blind'),
  (8722, 19, 'Bezahlkarte für Geflüchtete abschaffen und eigenes Konto ermöglichen (Land)', 'Beseitigt eine staatlich gesetzte Sonderbehandlung im Alltag (Bargeld- und Händlergrenzen), berührt den Rechtsschutz gegen Diskriminierung aber nur am Rand; die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8723, 19, 'Religiöse Feiertage und Praktiken im Landesrecht berücksichtigen (Land)', 'Baut einzelne staatliche Benachteiligungen religiöser Minderheiten ab (Feiertage, Ladenöffnung, Bestattung), betrifft aber kleine Gruppen und schafft keinen allgemeinen Rechtsschutz.', 'offen', null, 'land', null, true, 'blind'),
  (8724, 19, 'Landesförderung von Kinderwunschbehandlungen für gleichgeschlechtliche Paare und Alleinstehende öffnen (Land)', 'Beseitigt direkt eine Ungleichbehandlung in einer staatlichen Förderrichtlinie und ist per Richtlinie schnell umsetzbar; kostet zusätzliche Mittel, Wirkung über die Förderfälle hinaus nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8725, 19, 'Queersensible Verwaltungsregeln zu Namen, Pronomen, Geschlechtsangaben und Transition (Land)', 'Verringert Herabsetzungen im Umgang mit Behörden und im Landesdienst, betrifft aber Einzelaspekte und schafft keinen Rechtsschutz; die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8726, 19, 'Bundesratsinitiative zur Ergänzung von Art. 3 GG um sexuelle und geschlechtliche Identität (Land)', 'Stärkt den Verfassungsschutz vor staatlicher Diskriminierung, der aber durch Rechtsprechung weitgehend schon besteht; braucht Zweidrittelmehrheiten in Bundestag und Bundesrat, das Land kann nur anstoßen.', 'offen', null, 'land', null, true, 'blind'),
  (8727, 19, 'Bundesratsinitiative für eine Reform des Allgemeinen Gleichbehandlungsgesetzes (Land)', 'Eine AGG-Reform könnte Schutzlücken (Wohnungsmarkt, staatliches Handeln) schließen; das Land kann sie nur über den Bundesrat anstoßen, entscheiden muss der Bund.', 'offen', null, 'land', null, true, 'blind'),
  (8728, 19, 'Allgemeines Gleichbehandlungsgesetz reformieren: längere Fristen, Verbandsklage, staatliches Handeln (Bund)', 'Erleichtert die Durchsetzung bei Benachteiligung in Bewerbung und Alltag, wo bisher nur wenige klagen; für Behörden der Länder fehlt dem Bund teils die Kompetenz. Die Wirkung ist kaum gemessen.', 'offen', null, 'bund', null, true, 'blind'),
  (8729, 19, 'Art. 3 GG um sexuelle Identität oder Schutzklauseln erweitern (Bund)', 'Stärkt den verfassungsrechtlichen Schutz vor staatlicher Diskriminierung, ändert aber wenig am durch Rechtsprechung schon gewährten Schutz; Zweidrittelmehrheit in Bundestag und Bundesrat nötig.', 'offen', null, 'bund', null, true, 'blind'),
  (8730, 19, 'Racial Profiling bei der Bundespolizei gesetzlich verbieten und Kontrollquittungen einführen (Bund)', 'Der Bund ist für die Bundespolizei zuständig; Quittungen senkten in Fuenlabrada die Überrepräsentation bei Kontrollen. Belege stammen aus wenigen Pilotorten, ein Verbot allein ist ohne Dokumentation schwer überprüfbar.', 'offen', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'bund', null, true, 'blind'),
  (8731, 19, 'Antidiskriminierungs-Fortbildungen im öffentlichen Dienst des Bundes (Bund)', 'Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen nach; der Bund kann sie für eigene Beschäftigte anordnen und Angebote fördern.', 'gemischt', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'bund', null, true, 'blind'),
  (8732, 19, 'Antidiskriminierungsstelle des Bundes stärken und Beratungsangebote ausbauen (Bund)', 'Beratung ist bundesweit lückenhaft; mehr Kapazität hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Der Bund kann die Stelle ausstatten und Programme fördern.', 'offen', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'bund', null, true, 'blind'),
  (8733, 19, 'Bundesstrategien, Aktionspläne, Beauftragte und Förderprogramme gegen Rassismus und Queerfeindlichkeit (Bund)', 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'gemischt', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'bund', null, true, 'blind'),
  (8734, 19, 'Gedenkstättenbesuche von Schulklassen fördern (Bund)', 'Besuche können Impulse setzen, ersetzen laut Fachpraxis aber keine kontinuierliche Bildungsarbeit; belastbare Wirkungsstudien fehlen. Schule ist Ländersache, der Bund kann nur fördern.', 'offen', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'bund', null, true, 'blind'),
  (8735, 19, 'Stellenbesetzung ausschließlich nach Qualifikation, Quoten ablehnen (Bund)', 'Bestenauslese gilt bereits (Art. 33 GG, AGG); die Festlegung ändert nichts an der Benachteiligung bei gleicher Qualifikation, an der die Ursache ansetzt.', 'offen', null, 'bund', null, true, 'blind'),
  (8736, 19, 'Staatliche Förderung von Gender- und Vielfaltsthemen in Bildung und Kultur einstellen (Bund)', 'Der Bund kann eigene Förderung beenden; Angebote gegen die Abwertung sexueller und geschlechtlicher Vielfalt würden dadurch geschwächt statt gestärkt.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 19 and id not in (8706, 8707, 8708, 8709, 8710, 8711, 8712, 8713, 8714, 8715, 8716, 8717, 8718, 8719, 8720, 8721, 8722, 8723, 8724, 8725, 8726, 8727, 8728, 8729, 8730, 8731, 8732, 8733, 8734, 8735, 8736);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (8737, 19, 11, null, 'Alle Schülerinnen und Schüler sollen Gedenkstätten besuchen; Aufbau des Deutsch-Israelischen Jugendwerks vorantreiben', '{1902}', 8734, 1, 2, null, 'Besuche können Impulse setzen, ersetzen laut Fachpraxis aber keine kontinuierliche Bildungsarbeit; belastbare Wirkungsstudien fehlen. Schule ist Ländersache, der Bund kann nur fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'offen', '2026-10-10', false, true, 'blind'),
  (8738, 19, 11, 'BE', 'Schulunterricht soll sich mit antisemitischen und rassistischen Ideologien auseinandersetzen.', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8739, 19, 11, 'BE', 'Antisemitische, rassistische oder extremistische Graffiti innerhalb von 24 Stunden entfernen.', '{1902}', null, 1, 3, null, 'Schnelle Entfernung verringert sichtbare Herabwürdigung im öffentlichen Raum, wirkt auf Einstellungen aber kaum; bei privaten Flächen ist die Umsetzung schwierig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=79', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8740, 19, 11, 'BE', 'Beratungsangebote bei antisemitischen Vorfällen im Kulturbereich ausbauen und dauerhaft sichern.', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=23', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8741, 19, 11, 'BE', 'Antisemitische Vorfälle an Hochschulen benennen, aufklären und konsequent ahnden.', '{1902}', null, 1, 3, null, 'Konsequente Ahndung über Hausrecht und Ordnungsrecht schützt Betroffene an Hochschulen, wirkt aber vor allem im Einzelfall; Exmatrikulation ist rechtlich nur eng begrenzt möglich.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=23', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8742, 19, 11, 'BE', 'Projekte und Initiativen fördern, die demokratische Werte vermitteln und gegen gruppenbezogene Menschenfeindlichkeit eintreten.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=120', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8743, 19, 11, 'BE', 'Den Aktions- und Gedenktag gegen Islamfeindlichkeit abschaffen.', '{1902}', 8719, 0, 3, null, 'Haushaltsrechtlich leicht umsetzbar, schwächt aber Präventions-, Melde- und Unterstützungsangebote; ein Beitrag zum Abbau rassistischer Zuschreibungen ist nicht erkennbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=117', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8744, 19, 11, 'BE', 'Sexuelle Identität als Merkmal in Artikel 3 Grundgesetz aufnehmen und dafür eintreten.', '{1904}', 8726, 1, 1, null, 'Stärkt den Verfassungsschutz vor staatlicher Diskriminierung, der aber durch Rechtsprechung weitgehend schon besteht; braucht Zweidrittelmehrheiten in Bundestag und Bundesrat, das Land kann nur anstoßen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8745, 19, 11, 'BE', 'Landesantidiskriminierungsgesetz umfassend überarbeiten, damit es nicht über Bundesrecht hinausgeht.', '{1904}', 8707, 0, 3, null, 'Landesrechtlich ohne Weiteres möglich, verringert aber den Rechtsschutz gegen Diskriminierung durch Behörden, statt ihn zu stärken; die bestehende Ombudsstelle bearbeitet jährlich hunderte Anfragen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8746, 19, 11, 'BE', 'Doppelstrukturen bei Stellen für Diskriminierungsbeschwerden abbauen.', '{1904}', 8720, 0, 3, null, 'Spart Mittel und ist leicht umsetzbar, entfernt aber Anlaufstellen und Sensibilisierung gegen Diskriminierung durch Behörden; zum Ziel trägt es nicht bei.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=118', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8747, 19, 11, 'MV', 'Politische Bildung und klare Haltung gegen Antisemitismus und Hass sind Pflicht in der Schule; ein Gedenkstättenbesuch wird verpflichtend.', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=52', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8748, 19, 11, 'ST', 'Förderung von Initiativen, die Begegnung und Dialog ermöglichen und respektvolles Miteinander in religiöser Vielfalt stärken', '{1902}', 8716, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; vorregistrierte Experimente finden aber kleinere, oft auf die Beteiligten begrenzte Effekte. Die Reichweite einzelner Projekte ist gering.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=73', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8749, 19, 11, 'ST', 'Unterstützung jüdischen Lebens mit Synagogenneubau, Bildungsarbeit, Schutzmaßnahmen und Kampf gegen Antisemitismus', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=73', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8750, 19, 12, null, 'Allgemeines Gleichbehandlungsgesetz ausweiten, um den Schutz vor Diskriminierung zu stärken', '{1901}', null, 1, 3, null, 'Eine Ausweitung des AGG kann Diskriminierung bei Bewerbungen besser sanktionieren, bleibt ohne Angaben zum Inhalt aber unbestimmt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8751, 19, 12, null, 'Beratungsangebote gegen Diskriminierung ausbauen und die Antidiskriminierungsstelle des Bundes stärken', '{1902}', 8732, 1, 3, null, 'Beratung ist bundesweit lückenhaft; mehr Kapazität hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Der Bund kann die Stelle ausstatten und Programme fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8752, 19, 12, null, 'Vielfalt in Bildungsplänen, Schulbüchern und pädagogischen Berufen abbilden', '{1902}', null, 1, 1, null, 'Vielfalt in Lehrplänen und Schulbüchern kann Vorurteilen entgegenwirken, beides ist aber Ländersache; der Bund hat kaum Einfluss.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=16', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8753, 19, 12, 'BE', 'Rassismusprävention gemeinsam mit Communities weiterentwickeln und in einem Landeskonzept Antidiskriminierung bündeln', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8754, 19, 12, 'BE', 'Ausbau von Beratungsstellen gegen Diskriminierung', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8755, 19, 12, 'BE', 'An jeder Schule ein Anti-Mobbing-Team gegen Mobbing und gruppenfeindliches Verhalten', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8756, 19, 12, 'BE', 'Rahmenlehrplan, Curricula und Lehrmaterialien queer- und rassismussensibel überarbeiten', '{1902,1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8757, 19, 12, 'BE', 'Fortbildungen zu Diskriminierung und Rassismus sowie verpflichtende diskriminierungskritische Module in der Ausbildung pädagogischer Fachkräfte', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8758, 19, 12, 'BE', 'Sensibilisierung für Rassismus und Queerfeindlichkeit in Aus- und Fortbildung der Polizei stärken', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8759, 19, 12, 'BE', 'Ombudsstelle des Landesantidiskriminierungsgesetzes mit mehr Rechten ausstatten', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8760, 19, 12, 'BE', 'Leitstelle Diversity in der Verwaltung mit verbindlicher Schulung der Beschäftigten', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8761, 19, 12, 'BE', 'Antidiskriminierungsangebote an Hochschulen ausbauen und Beschwerdestrukturen schaffen', '{1904}', 8708, 2, 3, null, 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=45', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8762, 19, 12, 'BE', 'Queerbeauftragte in allen Bezirken einsetzen', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8763, 19, 12, 'BE', 'Queere Bildung in Schulen, Jugendarbeit und Erwachsenenbildung stärken', '{1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8764, 19, 12, 'BE', 'Queere Jugendzentren halten und ausbauen', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
