  (8766, 19, 12, 'BE', 'Transitionsrichtlinien für die Verwaltung zur Verbesserung der Lage queerer Beschäftigter', '{1904}', 8725, 1, 3, null, 'Verringert Herabsetzungen im Umgang mit Behörden und im Landesdienst, betrifft aber Einzelaspekte und schafft keinen Rechtsschutz; die Wirkung ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8767, 19, 12, 'BE', 'Queersensible Gesundheitsversorgung stärken und Aus- und Fortbildung in Gesundheitsberufen ausbauen', '{1903}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=34', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
