  (8784, 19, 12, 'ST', 'Landes-Antidiskriminierungsgesetz, das die Rechte von Betroffenen stärkt.', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8785, 19, 12, 'ST', 'Rassismuskritische Bildungsarbeit in Verwaltung, Schulen und Polizei ausbauen.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8786, 19, 12, 'ST', 'Verwaltung und öffentliche Einrichtungen sollen selbstgewählte Namen und Pronomen anerkennen.', '{1904}', 8725, 1, 3, null, 'Verringert Herabsetzungen im Umgang mit Behörden und im Landesdienst, betrifft aber Einzelaspekte und schafft keinen Rechtsschutz; die Wirkung ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=56', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8787, 19, 12, 'ST', 'Ansprechpersonen LSBTTI und Gleichstellungsbeauftragte bei der Polizei auf zwei hauptamtliche Stellen je Funktion ausbauen.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8788, 19, 13, null, 'Allgemeines Gleichbehandlungsgesetz reformieren: längere Fristen, mehr Diskriminierungsgründe, Verbandsklage, Schutz vor Diskriminierung durch staatliche Stellen', '{1901,1904}', 8728, 2, 2, null, 'Erleichtert die Durchsetzung bei Benachteiligung in Bewerbung und Alltag, wo bisher nur wenige klagen; für Behörden der Länder fehlt dem Bund teils die Kompetenz. Die Wirkung ist kaum gemessen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8789, 19, 13, null, 'Einstellungs- und Beförderungspraxis in Behörden diskriminierungssensibel gestalten', '{1901}', null, 1, 3, null, 'Setzt bei Einstellung und Beförderung in Bundesbehörden an, bleibt ohne konkretes Verfahren (etwa standardisierte Auswahl) aber unbestimmt; die Wirkung hängt von der Ausgestaltung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=117', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8790, 19, 13, null, 'Nationale Strategie gegen Islamfeindlichkeit und antimuslimischen Rassismus', '{1902}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=117', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8791, 19, 13, null, 'Beratungsstellen und Selbstorganisationen langfristig absichern und ausbauen; Antidiskriminierungsstelle des Bundes stärken', '{1902}', 8732, 1, 3, null, 'Beratung ist bundesweit lückenhaft; mehr Kapazität hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Der Bund kann die Stelle ausstatten und Programme fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8792, 19, 13, null, 'Allen Schüler*innen einen NS-Gedenkstättenbesuch ermöglichen und finanziell unterstützen', '{1902}', 8734, 1, 2, null, 'Besuche können Impulse setzen, ersetzen laut Fachpraxis aber keine kontinuierliche Bildungsarbeit; belastbare Wirkungsstudien fehlen. Schule ist Ländersache, der Bund kann nur fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=106', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'offen', '2026-10-10', false, true, 'blind'),
  (8793, 19, 13, null, 'Zielgerichtete Fortbildungsangebot zur Diskriminierungssensibilität in Gesundheitswesen, Justiz und Sicherheitsbehörden stärker fördern', '{1904}', 8731, 1, 3, null, 'Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen nach; der Bund kann sie für eigene Beschäftigte anordnen und Angebote fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8794, 19, 13, null, 'Ticketsystem für Polizeikontrollen, das die Gründe der Kontrolle darlegt', '{1904}', 8730, 2, 3, null, 'Der Bund ist für die Bundespolizei zuständig; Quittungen senkten in Fuenlabrada die Überrepräsentation bei Kontrollen. Belege stammen aus wenigen Pilotorten, ein Verbot allein ist ohne Dokumentation schwer überprüfbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'offen', '2026-10-10', false, true, 'blind'),
  (8795, 19, 13, null, 'Bundesförderprogramm für queere Beratungs- und Projektstrukturen aus dem Aktionsplan Queer leben', '{1903}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=121', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8796, 19, 13, 'BE', 'Gesamtstädtische Antidiskriminierungs- und Diversitätsstrategie, die bestehende Programme zusammenführt und alle Handlungsfelder auf strukturelle Diskriminierung prüft', '{1902,1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=135', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8797, 19, 13, 'BE', 'Förderprogramm für Selbstorganisationen marginalisierter Gruppen und Ausbau diskriminierungskritischer Beratung', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=136', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8798, 19, 13, 'BE', 'Novelle des Landesantidiskriminierungsgesetzes: erweiterter Merkmalskatalog, längere Verjährungsfrist, höhere Entschädigung, Rechtshilfefonds, gestärkte Ombudsstelle', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=136', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8799, 19, 13, 'BE', 'Neustart des Diversity-Landesprogramms mit Verbindlichkeit für alle Verwaltungen, verbindliche Beschwerdeverfahren bei Rassismus und Diskriminierung', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=137', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8800, 19, 13, 'BE', 'Einführung eines Diversitäts-Checks, der Senatsmaßnahmen vorab auf diskriminierende Wirkungen prüft', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=137', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8801, 19, 13, 'BE', 'Verbindliche Antidiskriminierungs- und Diversitätsstrategien für landeseigene Unternehmen, auch im Umgang mit Kundschaft', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=138', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8802, 19, 13, 'BE', 'Konsequente Umsetzung des Landeskonzepts zur Antisemitismus-Prävention und Schließen von Schutzlücken', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=139', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8803, 19, 13, 'BE', 'Landesbeauftragte*r gegen antimuslimische Diskriminierung, die Lücken in Behörden und Schulen schließt', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=140', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8804, 19, 13, 'BE', 'Abschaffung des Neutralitätsgesetzes im öffentlichen Dienst', '{1904}', null, 2, 3, null, 'Öffnet kopftuchtragenden Frauen den Staatsdienst; das BAG wertete das pauschale Verbot bereits als Diskriminierung. Die Aufhebung ist landesrechtlich einfach, Gegner verweisen auf Neutralität.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=140', 'https://www.evangelisch.de/inhalte/174171/27-08-2020/pauschales-kopftuchverbot-im-schulunterricht-diskriminierend', 'offen', '2026-10-10', false, true, 'blind'),
  (8805, 19, 13, 'BE', 'Verpflichtende Fortbildungen für Beschäftigte im öffentlichen Dienst zu antimuslimischem Rassismus', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=140', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8806, 19, 13, 'BE', 'Beratungs-, Melde- und Empowermentstrukturen gegen anti-Schwarzen Rassismus ausbauen und langfristig sichern', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=141', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8807, 19, 13, 'BE', 'Forschung und politische Bildung zu Antislawismus stärken, Sichtbarkeit und Teilhabe betroffener Menschen fördern', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=142', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8808, 19, 13, 'BE', 'Verbindliche Vermittlung antiziganismuskritischer Kenntnisse in Lehrplänen und in der Ausbildung pädagogischen Personals', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=142', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8809, 19, 13, 'BE', 'Ombudsstelle im Landesamt für Einwanderung wieder einrichten und zu einer mitwirkungsberechtigten Ombudsstelle weiterentwickeln', '{1904}', 8708, 2, 3, null, 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8810, 19, 13, 'BE', 'Einheitliche Beratungs- und Unterstützungsangebote für LSBTIQ* in allen Bezirken', '{1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=150', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8811, 19, 13, 'BE', 'Queerbeauftragte in allen Bezirken mit gesetzlicher Grundlage', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=150', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8812, 19, 13, 'BE', 'Schulung des Personals in Gerichten und Jugendämtern, um Diskriminierung von Regenbogenfamilien abzubauen', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=150', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
