  (8818, 19, 13, 'BE', 'Umsetzung einer zentralen Beschwerdestelle nach dem AGG für öffentliche Kulturbetriebe', '{1904}', 8708, 2, 3, null, 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=164', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8819, 19, 13, 'BE', 'Ladenschlussgesetz so ändern, dass jüdische Geschäfte mit koscheren Lebensmitteln am Sonntag statt Samstag öffnen können', '{1904}', 8723, 1, 3, null, 'Baut einzelne staatliche Benachteiligungen religiöser Minderheiten ab (Feiertage, Ladenöffnung, Bestattung), betrifft aber kleine Gruppen und schafft keinen allgemeinen Rechtsschutz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=170', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8820, 19, 13, 'BE', 'Stärkung des Schutzes jüdischer und muslimischer Feiertage', '{1904}', 8723, 1, 3, null, 'Baut einzelne staatliche Benachteiligungen religiöser Minderheiten ab (Feiertage, Ladenöffnung, Bestattung), betrifft aber kleine Gruppen und schafft keinen allgemeinen Rechtsschutz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=170', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8821, 19, 13, 'BE', 'Liberalisierung der gesetzlichen Bestattungsvorgaben, damit sich Bestattungen nach religiösen oder nichtreligiösen Vorstellungen richten können', '{1904}', 8723, 1, 3, null, 'Baut einzelne staatliche Benachteiligungen religiöser Minderheiten ab (Feiertage, Ladenöffnung, Bestattung), betrifft aber kleine Gruppen und schafft keinen allgemeinen Rechtsschutz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=170', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8822, 19, 13, 'BE', 'Unterstützung des Dialogs der Glaubensgemeinschaften und interreligiöser Formen des Gedenkens', '{1902}', 8716, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; vorregistrierte Experimente finden aber kleinere, oft auf die Beteiligten begrenzte Effekte. Die Reichweite einzelner Projekte ist gering.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=171', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8823, 19, 13, 'BE', 'Unabhängige Beschwerdestelle gegen Diskriminierung an Schulen als eigene Behörde unter dem Dach der LADG-Ombudsstelle', '{1904}', 8708, 2, 3, null, 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8824, 19, 13, 'BE', 'Beendigung der separierenden Unterbringung und Beschulung von Kindern in Flüchtlingsunterkünften', '{1904}', null, 2, 2, null, 'Beendet die getrennte Beschulung in Unterkünften und ermöglicht Regelschule und Kontakt; landesrechtlich umsetzbar, erfordert aber Schulplätze und Personal. Wirkungen sind wenig untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8825, 19, 13, 'BE', 'Diversitäts- und rassismussensible Forschung im Gesundheitswesen fördern und in die Ausbildung des Gesundheitspersonals integrieren', '{1902}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=205', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8826, 19, 13, 'BE', 'Ausweitung der LSBTIQ*-sensiblen Beratung und verpflichtende Weiterbildung zu diversitätssensibler Pflege', '{1903}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=215', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8827, 19, 13, 'BE', 'Pilotprojekt zur Sensibilisierung von Verantwortlichen für die Bedürfnisse queerer Seniorinnen und Senioren', '{1903}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=218', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8828, 19, 13, 'BE', 'Strukturen der Sicherheitsbehörden diskriminierungskritisch hinterfragen', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8829, 19, 13, 'BE', 'Weiterentwicklung der Fanarbeit, Awareness-Strukturen und Konflikttraining gegen Diskriminierung im Stadion', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=41', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8830, 19, 13, 'BE', 'Fachstelle gegen Diskriminierung auf dem Wohnungsmarkt weiter stärken', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=49', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8831, 19, 13, 'BE', 'Stärkung des Diskriminierungsschutzes auf dem Wohnungsmarkt im Allgemeinen Gleichbehandlungsgesetz auf Bundesebene', '{1902}', 8727, 2, 1, null, 'Eine AGG-Reform könnte Schutzlücken (Wohnungsmarkt, staatliches Handeln) schließen; das Land kann sie nur über den Bundesrat anstoßen, entscheiden muss der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8832, 19, 13, 'BE', 'Umsetzung des Leitbilds diskriminierungsarmen Vermietens bei landeseigenen Wohnungsunternehmen', '{1902}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=55', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8833, 19, 13, 'BE', 'Verwaltungsprozesse diskriminierungsfrei gestalten, mit verbindlichen Standards, Fortbildungen und Beschwerdewegen', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=71', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8834, 19, 13, 'BE', 'Ausbau von Beratung und Spezialangeboten für besonders vulnerable Gruppen, darunter LSBTIQ*', '{1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=73', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8835, 19, 13, 'BE', 'Unterstützung von Arbeitgeber*innen und AGG-Beschwerdestellen für ein diskriminierungssensibles Arbeitsumfeld', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=104', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8836, 19, 13, 'MV', 'Unabhängige Beratungs- und Unterstützungsstrukturen im ganzen Land ausbauen und langfristig finanzieren', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=86', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8837, 19, 13, 'MV', 'Landesprogramm Demokratie und Toleranz gesetzlich verankern (Grenzfall: allgemeines Demokratieprogramm)', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://gruene-mv.de/?wpdmdl=33772#page=68', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8838, 19, 13, 'MV', 'Systematische Datenerfassung zu Diskriminierung, um sie sichtbar zu machen', '{1902}', 8718, 1, 3, null, 'Verbessert die Grundlage für gezielte Maßnahmen, verändert Einstellungen oder Benachteiligung aber nicht selbst.', 'https://gruene-mv.de/?wpdmdl=33772#page=86', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8839, 19, 13, 'MV', 'Beratungs- und Unterstützungsangebote für queere Menschen langfristig ausbauen, auch im ländlichen Raum', '{1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=87', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8840, 19, 13, 'MV', 'Queere Lebensrealitäten sichtbarer machen und in Bildung, Ausbildung und öffentlichem Leben verankern', '{1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=87', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8841, 19, 13, 'MV', 'Mit einem Landes-Antidiskriminierungsgesetz Beratungsstellen absichern und Diskriminierung beklagbar machen', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8842, 19, 13, 'MV', 'Verpflichtende Weiterbildungen für Fachkräfte und Polizei, um Mehrfachdiskriminierung queerer Menschen zu verhindern', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://gruene-mv.de/?wpdmdl=33772#page=87', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8843, 19, 13, 'MV', 'Landesverwaltung interkulturell öffnen, sodass Verwaltungsleistungen unabhängig von der Herkunft zugänglich sind', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=91', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8844, 19, 13, 'MV', 'Polizeigesetz mit Vorkehrungen gegen Racial Profiling', '{1904}', 8710, 2, 3, null, 'Setzt an Befugnissen an, die diskriminierende Kontrollen ermöglichen, und ist im Landespolizeirecht regelbar; Studien zur Wirkung einer Abschaffung solcher Befugnisse fehlen, Sicherheitsfolgen sind umstritten.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8845, 19, 13, 'MV', 'Verbot diskriminierender KI-Anwendungen in Sicherheitsbehörden, etwa Predictive Policing', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=75', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8846, 19, 13, 'MV', 'Bezahlkarte für Geflüchtete abschaffen und eigenes Konto ermöglichen', '{1904}', 8722, 1, 3, null, 'Beseitigt eine staatlich gesetzte Sonderbehandlung im Alltag (Bargeld- und Händlergrenzen), berührt den Rechtsschutz gegen Diskriminierung aber nur am Rand; die Wirkung ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=92', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8847, 19, 13, 'ST', 'Landesantidiskriminierungsgesetz: Diskriminierung durch staatliche Stellen verhindern, Betroffenen rechtliches Gehör und Entschädigung ermöglichen', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=51', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8848, 19, 13, 'ST', 'Aus- und Fortbildung der Polizei auf Antidiskriminierung ausrichten; regelmäßige Fortbildungen gegen Racial Profiling', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8849, 19, 13, 'ST', 'Verbindliche regelmäßige Fortbildungen für Lehrkräfte zum Umgang mit Diskriminierung', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8850, 19, 13, 'ST', 'Landesweite unabhängige Ombudsstelle für Diskriminierung und Übergriffe an Schulen, anonyme Meldung und Beratung', '{1904}', 8708, 2, 3, null, 'Schafft niedrigschwellige Abhilfe dort, wo Beschwerden über staatliche Diskriminierung häufig sind (Schulen, Hochschulen); ohne eigene Klagerechte bleibt die Durchsetzung begrenzt, Wirkungsstudien fehlen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8851, 19, 13, 'ST', 'Öffnung der Landesförderung künstlicher Befruchtung für queere Paare und ledige Frauen', '{1904}', 8724, 2, 3, null, 'Beseitigt direkt eine Ungleichbehandlung in einer staatlichen Förderrichtlinie und ist per Richtlinie schnell umsetzbar; kostet zusätzliche Mittel, Wirkung über die Förderfälle hinaus nicht untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=82', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8852, 19, 13, 'ST', 'Schutz von Kindern vor Diskriminierung, Rassismus und Queerfeindlichkeit an Schulen durch Beratung, Präventionsprogramme und Netzwerke', '{1902,1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8853, 19, 13, 'ST', 'Prävention und Bildung gegen Rassismus und gruppenbezogene Menschenfeindlichkeit; Bildungsarbeit und Antidiskriminierungsprojekte stärken', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8854, 19, 13, 'ST', 'Projekte gegen Rassismus, Islamfeindlichkeit und Queerfeindlichkeit stärken und verlässlich fördern', '{1902,1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=75', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8855, 19, 13, 'ST', 'Fachzentren für geschlechtliche Vielfalt als Beratungs- und Versorgungsstellen für trans, inter und nichtbinäre Personen finanzieren', '{1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8856, 19, 13, 'ST', 'Aktionsprogramm für die Akzeptanz queerer Menschen konsequent weiterentwickeln und umsetzen', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8857, 19, 13, 'ST', 'Institutionelle Strukturen für eine konsequente Queer-Politik im Land aufbauen', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8858, 19, 14, null, 'Verpflichtende Besuche von Gedenkstätte und Synagoge sowie Auseinandersetzung mit Antisemitismus im Schulunterricht', '{1902}', null, 1, 1, null, 'Pflichtbesuche können Impulse setzen, ihre Wirkung ist nicht belegt; Lehrpläne und Schulpflichten sind Ländersache, der Bund kann sie nicht vorschreiben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'offen', '2026-10-10', false, true, 'blind'),
  (8859, 19, 14, null, 'Nationalen Aktionsplan „Queer leben“ umsetzen und Bundesstiftung Magnus Hirschfeld besser ausstatten, gegen Diskriminierung von LSBTI', '{1903}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8860, 19, 14, null, 'Sexuelle Identität in den Gleichheitsartikel des Grundgesetzes aufnehmen', '{1904}', 8729, 1, 1, null, 'Stärkt den verfassungsrechtlichen Schutz vor staatlicher Diskriminierung, ändert aber wenig am durch Rechtsprechung schon gewährten Schutz; Zweidrittelmehrheit in Bundestag und Bundesrat nötig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8861, 19, 14, null, 'IHRA-Arbeitsdefinition von Antisemitismus in Behörden etablieren und Grundlage von Fortbildungen für Beamtinnen und Beamte machen', '{1904}', 8731, 1, 3, null, 'Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen nach; der Bund kann sie für eigene Beschäftigte anordnen und Angebote fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8862, 19, 14, 'BE', 'Beweislastregel (Vermutungsregelung) im Landesantidiskriminierungsgesetz abschaffen', '{1904}', 8707, 0, 3, null, 'Landesrechtlich ohne Weiteres möglich, verringert aber den Rechtsschutz gegen Diskriminierung durch Behörden, statt ihn zu stärken; die bestehende Ombudsstelle bearbeitet jährlich hunderte Anfragen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8863, 19, 14, 'BE', 'Anspruch auf Ersatz- oder Ausweichtermine bei religiösen Feiertagen in Schulen und Hochschulen', '{1904}', null, 2, 3, null, 'Ein Anspruch auf Ersatztermine beseitigt eine konkrete Benachteiligung religiöser Schüler und Studierender durch staatliche Einrichtungen; im Schul- und Hochschulrecht einfach regelbar, betrifft aber kleine Gruppen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=78', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8864, 19, 14, 'BE', 'Antisemitismus-Arbeitsdefinition (IHRA) in staatlichen Behörden etablieren; Behörden sensibilisieren', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=78', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8865, 19, 14, 'BE', 'Bildungsprogramme gegen Antisemitismus in Schulen verbindlich verankern, mit Begegnungsformaten', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8866, 19, 14, 'BE', 'Vorurteilsfreie Begleitung von Transitionen und queersensible Versorgung im ganzen Stadtgebiet', '{1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=117', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8867, 19, 14, 'BE', 'Landesfinanzierung von Kinderwunschbehandlungen darf gleichgeschlechtliche Paare und Alleinstehende nicht schlechterstellen', '{1904}', 8724, 2, 3, null, 'Beseitigt direkt eine Ungleichbehandlung in einer staatlichen Förderrichtlinie und ist per Richtlinie schnell umsetzbar; kostet zusätzliche Mittel, Wirkung über die Förderfälle hinaus nicht untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=82', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8868, 19, 14, 'ST', 'Diskriminierung in Jugendarbeit und Schule entgegenwirken und mit Aufklärung für Toleranz und Akzeptanz werben.', '{1902,1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8869, 19, 14, 'ST', 'Feste Ansprechpersonen für Antidiskriminierung in der Polizei aufbauen.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8870, 19, 14, 'ST', 'Konsequente, nachhaltige Fortbildung zur Antidiskriminierung für die Polizei.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8871, 19, 14, 'ST', 'Geschlechtsangabe in der Verwaltung nur dort erfassen, wo es unbedingt nötig ist.', '{1904}', 8725, 1, 3, null, 'Verringert Herabsetzungen im Umgang mit Behörden und im Landesdienst, betrifft aber Einzelaspekte und schafft keinen Rechtsschutz; die Wirkung ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8872, 19, 15, null, 'Öffentliche Ämter, Beamten- und Richterstellen allein nach Eignung und Leistung vergeben; Quotenregelungen ablehnen', '{1901}', 8735, 0, 3, null, 'Bestenauslese gilt bereits (Art. 33 GG, AGG); die Festlegung ändert nichts an der Benachteiligung bei gleicher Qualifikation, an der die Ursache ansetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=137', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8873, 19, 15, null, 'Bei der Besetzung von Stellen soll allein die fachliche Qualifikation der Bewerber entscheiden', '{1901}', 8735, 0, 3, null, 'Bestenauslese gilt bereits (Art. 33 GG, AGG); die Festlegung ändert nichts an der Benachteiligung bei gleicher Qualifikation, an der die Ursache ansetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=164', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8874, 19, 15, null, 'Studienplätze für Medizin und Zahnmedizin vorrangig an Bewerber mit deutscher Staatsangehörigkeit', '{1901}', null, 0, 0, null, 'Vorrang nach Staatsangehörigkeit bei Studienplätzen verstößt gegen das EU-Diskriminierungsverbot (Art. 18 AEUV) und erhöht Benachteiligung nach Herkunft, statt sie abzubauen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=34', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8875, 19, 15, null, 'Kopftuchverbot in öffentlichen Einrichtungen und vor allem in Schulen', '{1904}', null, 0, 0, null, 'Pauschale Kopftuchverbote im öffentlichen Dienst sind nach BVerfG und BAG mit der Glaubensfreiheit unvereinbar, Schulen sind zudem Ländersache; das Verbot verstärkt Benachteiligung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=126', 'https://www.evangelisch.de/inhalte/174171/27-08-2020/pauschales-kopftuchverbot-im-schulunterricht-diskriminierend', 'offen', '2026-10-10', false, true, 'blind'),
  (8876, 19, 15, null, 'Verbot von Burka und Niqab in der Öffentlichkeit', '{1904}', null, 0, 1, null, 'Ein allgemeines Verschleierungsverbot hält der EGMR für zulässig, die Bundeskompetenz ist aber unklar; es schränkt eine religiöse Minderheit ein und baut Diskriminierung nicht ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=126', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8877, 19, 15, null, 'Verbot von Minaretten und Muezzinruf', '{1904}', null, 0, 0, null, 'Ein Verbot von Minaretten und Gebetsruf greift gezielt in die Religionsfreiheit einer Religion ein (Art. 4, Art. 3 Abs. 3 GG) und wäre so nicht verfassungsgemäß; es verstärkt staatliche Ungleichbehandlung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=125', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8878, 19, 15, null, 'Keine Indoktrination von Kindern und Jugendlichen; staatliche Förderung dafür einstellen', '{1903}', 8736, 0, 3, null, 'Der Bund kann eigene Förderung beenden; Angebote gegen die Abwertung sexueller und geschlechtlicher Vielfalt würden dadurch geschwächt statt gestärkt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=152', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8879, 19, 15, null, 'Indoktrination zu Gender-Themen in der Erzieherausbildung unterbinden', '{1903}', null, 0, 1, null, 'Die Erzieherausbildung ist Ländersache; die Maßnahme würde Sensibilisierung für geschlechtliche Vielfalt eher abbauen als Abwertung verringern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8880, 19, 15, null, 'Vorgaben der Filmförderung zu Gender- oder Vielfaltsthemen ablehnen', '{1903}', 8736, 0, 3, null, 'Der Bund kann eigene Förderung beenden; Angebote gegen die Abwertung sexueller und geschlechtlicher Vielfalt würden dadurch geschwächt statt gestärkt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=175', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8881, 19, 15, 'BE', 'Landesantidiskriminierungsgesetz aufheben und sicherheitsrelevante Gesetze überarbeiten', '{1904}', 8707, 0, 3, null, 'Landesrechtlich ohne Weiteres möglich, verringert aber den Rechtsschutz gegen Diskriminierung durch Behörden, statt ihn zu stärken; die bestehende Ombudsstelle bearbeitet jährlich hunderte Anfragen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8882, 19, 15, 'BE', 'Antisemitismusprävention im Schulunterricht ausbauen und verankern', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8883, 19, 15, 'BE', 'Verbot grenzüberschreitender Thematisierung von Sexualität in Kitas und Schulen', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8884, 19, 15, 'BE', 'Beauftragtenwesen, auch Antidiskriminierungsbeauftragte, abschaffen', '{1904}', 8720, 0, 3, null, 'Spart Mittel und ist leicht umsetzbar, entfernt aber Anlaufstellen und Sensibilisierung gegen Diskriminierung durch Behörden; zum Ziel trägt es nicht bei.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8885, 19, 15, 'BE', 'Schwerpunkt der Lehrkräftebildung weg von Diversity, Queer und Gender verlagern', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8886, 19, 15, 'BE', 'Neutralitätsgesetz bei Justiz und Polizei strikt durchsetzen (Verbot sichtbarer religiöser Symbole)', '{1904}', null, 0, 3, null, 'Strikte Durchsetzung des Neutralitätsgesetzes in Justiz und Polizei ist nach Rechtsprechung möglich, schließt aber kopftuchtragende Frauen von diesen Berufen aus und verringert Benachteiligung nicht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8887, 19, 15, 'BE', 'Gesetz: Kopftuchverbot für Mädchen unter 14 Jahren in Schulen', '{1904}', null, 0, 1, null, 'Ein Kopftuchverbot für Schülerinnen greift eine Religion heraus; Österreichs Verfassungsgerichtshof hob ein solches Verbot 2020 als gleichheitswidrig auf. Es verstärkt staatliche Ungleichbehandlung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=26', 'https://orf.at/stories/3193386/', 'offen', '2026-10-10', false, true, 'blind'),
  (8888, 19, 15, 'MV', 'Staatliche Förderung von Genderideologie und Frühsexualisierung in Kitas und Schulen einstellen', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8889, 19, 15, 'MV', 'Schulische Lehrinhalte am Familienbild der Mehrheit ausrichten', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8890, 19, 15, 'MV', 'Regenbogenflaggen und andere nicht hoheitliche Flaggen vor öffentlichen Einrichtungen untersagen', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=42', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8891, 19, 15, 'MV', 'Landesförderung für Vereine beenden, die der Polizei pauschal Rassismus unterstellen', '{1902}', 8719, 0, 3, null, 'Haushaltsrechtlich leicht umsetzbar, schwächt aber Präventions-, Melde- und Unterstützungsangebote; ein Beitrag zum Abbau rassistischer Zuschreibungen ist nicht erkennbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8892, 19, 15, 'MV', 'Dokumentationspflichten im Polizeigesetz (SOG) zurücknehmen', '{1904}', null, 0, 3, null, 'Die Rücknahme der Dokumentationspflichten ist landesrechtlich möglich, nimmt aber ein Instrument zur Überprüfung diskriminierender Kontrollen weg.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8893, 19, 15, 'MV', 'Interkulturelle Kompetenz als Schulungsinhalt in der Verwaltung beenden', '{1904}', 8720, 0, 3, null, 'Spart Mittel und ist leicht umsetzbar, entfernt aber Anlaufstellen und Sensibilisierung gegen Diskriminierung durch Behörden; zum Ziel trägt es nicht bei.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8894, 19, 15, 'ST', 'Landesweite Werbe- und Aufklärungskampagnen sollen Kinder und Familie in den Mittelpunkt stellen, auch in Schule und Bildung.', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=13', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8895, 19, 15, 'ST', 'Staatliche Kampagnen und Programme, die Kinder vor der Pubertät mit sexuellen Themen konfrontieren, sollen eingestellt werden.', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=22', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8896, 19, 15, 'ST', 'An Schulen soll per Runderlass keine Regenbogenfahne mehr gezeigt werden.', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=77', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8897, 19, 15, 'ST', 'Fördermittel sollen nicht mehr nach bestimmten Genderzielen oder queerbezogenen Anforderungen vergeben werden.', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=192', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8898, 19, 15, 'ST', 'Die Landeszentrale für politische Bildung soll in ihrer jetzigen Form abgeschafft und durch ein anderes Landesinstitut ersetzt werden.', '{1902}', 8719, 0, 3, null, 'Haushaltsrechtlich leicht umsetzbar, schwächt aber Präventions-, Melde- und Unterstützungsangebote; ein Beitrag zum Abbau rassistischer Zuschreibungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=61', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8899, 19, 15, 'ST', 'Landesförderung des Schulprogramms gegen Rassismus soll eingestellt werden.', '{1902}', 8719, 0, 3, null, 'Haushaltsrechtlich leicht umsetzbar, schwächt aber Präventions-, Melde- und Unterstützungsangebote; ein Beitrag zum Abbau rassistischer Zuschreibungen ist nicht erkennbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=77', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8900, 19, 15, 'ST', 'Alle Kinder von Flüchtlingen und Asylbewerbern sollen in Sonderklassen unterrichtet werden.', '{1904}', null, 0, 1, null, 'Sonderklassen für alle geflüchteten Kinder unabhängig vom Sprachstand trennen nach Herkunft bzw. Status und kollidieren mit Art. 3 GG und der UN-Kinderrechtskonvention; Benachteiligung nimmt eher zu.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=88', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8901, 19, 15, 'ST', 'Landesstellen für Gleichstellung, Integration und Diversity sollen abgeschafft werden.', '{1904}', 8720, 0, 3, null, 'Spart Mittel und ist leicht umsetzbar, entfernt aber Anlaufstellen und Sensibilisierung gegen Diskriminierung durch Behörden; zum Ziel trägt es nicht bei.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=215', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8902, 19, 16, null, 'Anonymisierte Bewerbungsverfahren, damit alle die gleichen Chancen auf einen Ausbildungsplatz haben', '{1901}', null, 2, 2, null, 'Anonymisierung setzt direkt an der Vorauswahl an; ein deutsches Pilotprojekt fand bessere Einladungschancen, ein französisches Experiment dagegen größere Nachteile für Minderheiten. Eine Pflicht für Betriebe wäre aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', 'https://www.povertyactionlab.org/evaluation/cv-anonymes', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8903, 19, 16, null, 'Quoten für von Diskriminierung betroffene Gruppen bei Einstellung und in weiteren Lebensbereichen', '{1901}', null, 2, 1, null, 'Quoten erhöhen die Repräsentation unmittelbar; Quoten nach Herkunft in der Privatwirtschaft sind aber mit Art. 3 Abs. 3 GG und EU-Recht schwer vereinbar, die Merkmale werden zudem nicht erfasst.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8904, 19, 16, null, 'Demokratiefördergesetz, das Opferberatungen und Projekte gegen Rechtsextremismus langfristig finanziell absichert', '{1902}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8905, 19, 16, null, 'Beauftragte*r gegen Rassismus auf Bundesebene', '{1902}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8906, 19, 16, null, 'Ausfinanzierter Aktionsplan gegen queerfeindliche Diskriminierung (Aktionsplan „Queer leben“)', '{1903}', 8733, 1, 3, null, 'Bündelt und finanziert Präventionsarbeit, die der Bund bereits fördert; Studien zum Vorurteilsabbau zeigen meist kleine, kurzfristige Effekte und Hinweise auf Publikationsverzerrung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8907, 19, 16, null, 'Queere Orte und Projekte vor Verdrängung schützen, queere Jugendarbeit als kommunale Pflichtaufgabe', '{1903}', null, 1, 1, null, 'Schutzräume und Jugendarbeit stärken queere Jugendliche, verändern Einstellungen aber nur mittelbar; eine kommunale Pflichtaufgabe kann der Bund wegen Art. 84 Abs. 1 S. 7 GG nicht direkt schaffen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8908, 19, 16, null, 'Betriebliche Selbstorganisation queerer Beschäftigter und Beschwerdestellen nach dem AGG gegen schlechtere Bezahlung', '{1903}', null, 1, 2, null, 'AGG-Beschwerdestellen sind bereits Pflicht; betriebliche Selbstorganisation kann der Bund nur anregen, nicht vorschreiben. Die Wirkung auf Abwertung am Arbeitsplatz ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8909, 19, 16, null, 'Reform des Allgemeinen Gleichbehandlungsgesetzes mit Verbandsklagerecht, längeren Klagefristen und Einbeziehung staatlichen Handelns', '{1904,1901}', 8728, 2, 2, null, 'Erleichtert die Durchsetzung bei Benachteiligung in Bewerbung und Alltag, wo bisher nur wenige klagen; für Behörden der Länder fehlt dem Bund teils die Kompetenz. Die Wirkung ist kaum gemessen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8910, 19, 16, null, 'Verpflichtende Antidiskriminierungsschulungen im gesamten öffentlichen Dienst', '{1904}', 8731, 1, 3, null, 'Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen nach; der Bund kann sie für eigene Beschäftigte anordnen und Angebote fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8911, 19, 16, null, 'Gesetzliches Verbot rassistischer Polizeikontrollen (Racial Profiling)', '{1904}', 8730, 2, 3, null, 'Der Bund ist für die Bundespolizei zuständig; Quittungen senkten in Fuenlabrada die Überrepräsentation bei Kontrollen. Belege stammen aus wenigen Pilotorten, ein Verbot allein ist ohne Dokumentation schwer überprüfbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'offen', '2026-10-10', false, true, 'blind'),
  (8912, 19, 16, null, 'Schutz- und Förderklausel im Grundgesetz für Betroffene rassistischer Diskriminierung', '{1904}', 8729, 1, 1, null, 'Stärkt den verfassungsrechtlichen Schutz vor staatlicher Diskriminierung, ändert aber wenig am durch Rechtsprechung schon gewährten Schutz; Zweidrittelmehrheit in Bundestag und Bundesrat nötig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8913, 19, 16, null, 'Geldleistungen statt diskriminierender Sachleistungen und Bezahlkarten für Geflüchtete', '{1904}', null, 1, 1, null, 'Ersetzt eine Sonderbehandlung Geflüchteter durch Geldleistungen und berührt Diskriminierung nur am Rand; die damit verbundene Mindestsicherung für alle ist sehr teuer und ungeklärt finanziert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8914, 19, 16, 'BE', 'Kampf gegen Rassismus und Antisemitismus stärken; die Arbeit dagegen langfristig und unabhängig von Förderperioden absichern.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=268', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8915, 19, 16, 'BE', 'Fachstellen gegen Diskriminierung (u. a. Wohnungs-, Arbeitsmarkt, Gesundheit) stärken und dauerhaft absichern.', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=269', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8916, 19, 16, 'BE', 'Dunkelfeldstudien zu Rassismus, Antisemitismus und weiteren Diskriminierungsformen durchführen lassen.', '{1902}', 8718, 1, 3, null, 'Verbessert die Grundlage für gezielte Maßnahmen, verändert Einstellungen oder Benachteiligung aber nicht selbst.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=269', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8917, 19, 16, 'BE', 'Empowermentarbeit für alle Berliner Communitys fördern.', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=269', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8918, 19, 16, 'BE', 'Förderung von Nichtregierungsorganisationen gegen Diskriminierung über ein Demokratiefördergesetz absichern, mit Qualitätskriterien.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8919, 19, 16, 'BE', 'Projekte stärken, die antisemitische Vorfälle erfassen, Opfer beraten und präventiv arbeiten; Antisemitismusprävention ausbauen.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8920, 19, 16, 'BE', 'Landesprogramm gegen Antiziganismus und zur Teilhabe von Rom*nja entwickeln; Ansprechperson stärken.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=271', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8921, 19, 16, 'BE', 'Ressortübergreifende Strategie gegen antimuslimischen Rassismus entwickeln und umsetzen, auch für den digitalen Raum.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8922, 19, 16, 'BE', 'Inhalte zur kolonialen Stadtgeschichte verbindlich in den Schulen vermitteln.', '{1902}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8923, 19, 16, 'BE', 'Diskriminierungskritische Jugendarbeit und Schulsozialarbeit strukturell stärken.', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=281', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8924, 19, 16, 'BE', 'Außerschulische Bildungs- und Empowermentangebote gegen Diskriminierung an Schulen absichern und verstetigen.', '{1902,1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8925, 19, 16, 'BE', 'Antirassismus sowie feministische und queere Projekte in allen Bezirken der Jugendarbeit fördern.', '{1902,1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=179', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8926, 19, 16, 'BE', 'Sportvereine sollen sich im Bereich Antidiskriminierung fortbilden und zertifizieren lassen können.', '{1902}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=314', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8927, 19, 16, 'BE', 'Unabhängige Monitoring- und Beschwerdestelle für Diskriminierung im Sport einrichten.', '{1902,1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=314', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8928, 19, 16, 'BE', 'Queere Sportvereine stärken und Queerfeindlichkeit im Sport aktiv bekämpfen.', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=314', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8929, 19, 16, 'BE', 'Fanszenen und Fanhilfen in ihrem Engagement gegen Diskriminierung, Rassismus und Queerfeindlichkeit im Stadion unterstützen.', '{1902,1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=323', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8930, 19, 16, 'BE', 'Beratungsangebote, Opferhilfe und anonyme Beschwerdestellen bei rechten Vorfällen strukturell und finanziell stärken.', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=326', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8931, 19, 16, 'BE', 'Verpflichtende Aus- und Weiterbildung zu Diskriminierung und Rassismus für Beschäftigte in Bildung, Sozialem, öffentlichem Dienst und Sicherheit.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8932, 19, 16, 'BE', 'Unterstützungsangebote für von Benachteiligung betroffene Gruppen, auch queere Personen, an Hochschulen ausbauen.', '{1902,1903}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=222', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8933, 19, 16, 'BE', 'Gesamter öffentlicher Dienst soll diskriminierungskritisch aufgestellt und geschult werden.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=268', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8934, 19, 16, 'BE', 'Themen Rassismus, Antisemitismus und koloniales Erbe fester Bestandteil der Aus- und Weiterbildung von Lehrkräften.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=269', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8935, 19, 16, 'BE', 'Landesantidiskriminierungsgesetz evaluieren, weiterentwickeln und Schutzlücken schließen.', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8936, 19, 16, 'BE', 'Ombudsstelle gegen Diskriminierung durch Behörden personell stärken und mit mehr Befugnissen ausstatten.', '{1904}', 8706, 2, 3, null, 'Schließt direkt die Lücke im Rechtsschutz gegen staatliche Diskriminierung; in Berlin wird die Ombudsstelle rege genutzt (166 Verfahren 2025). Eine Wirkungsevaluation, ob Diskriminierung dadurch abnimmt, fehlt bisher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-10', false, true, 'blind'),
  (8937, 19, 16, 'BE', 'Breit angelegte Informationskampagne zu Rechten gegen Diskriminierung durch Behörden.', '{1904}', null, 1, 3, null, 'Macht Beschwerde- und Klagemöglichkeiten gegen Diskriminierung durch Behörden bekannter; schafft selbst keinen neuen Schutz, die Wirkung solcher Kampagnen ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8938, 19, 16, 'BE', 'Vehementes Vorgehen gegen Racial Profiling durch staatliche Stellen.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8939, 19, 16, 'BE', 'Novellierung des Allgemeinen Gleichbehandlungsgesetzes per Bundesratsinitiative, auch Schutzlücken im staatlichen Handeln schließen.', '{1904}', 8727, 2, 1, null, 'Eine AGG-Reform könnte Schutzlücken (Wohnungsmarkt, staatliches Handeln) schließen; das Land kann sie nur über den Bundesrat anstoßen, entscheiden muss der Bund.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8940, 19, 16, 'BE', 'Alle Einrichtungen, insbesondere Polizei und ihre Datenbanken, diskriminierungskritisch überprüfen und Praktiken beenden.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8941, 19, 16, 'BE', 'Fortbildung zur Diskriminierungssensibilisierung für Mitglieder der Härtefallkommission.', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=279', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8942, 19, 16, 'BE', 'Zugriffsberechtigungen und Speicherung in Verwaltungsdatenbanken diskriminierungskritisch überprüfen.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=286', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8943, 19, 16, 'BE', 'Kriminalitätsbelastete Orte und Waffenverbotszonen abschaffen, da sie Racial Profiling begünstigen.', '{1904}', 8710, 2, 3, null, 'Setzt an Befugnissen an, die diskriminierende Kontrollen ermöglichen, und ist im Landespolizeirecht regelbar; Studien zur Wirkung einer Abschaffung solcher Befugnisse fehlen, Sicherheitsfolgen sind umstritten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-10', false, true, 'blind'),
