  (8945, 19, 16, 'BE', 'Rassistische Polizeipraktiken offenlegen und bekämpfen; Beratungsstellen unterstützen, die polizeiliches Handeln beobachten.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-10', false, true, 'blind'),
