  (8966, 19, 16, 'MV', 'Landesaktionsplan für Akzeptanz sexueller und geschlechtlicher Vielfalt finanzieren und fortführen', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8967, 19, 16, 'MV', 'Queeres Leben im Rahmenplan der Schulen verankern', '{1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8968, 19, 16, 'MV', 'Antidiskriminierungsberatungsstellen erhalten und ausbauen', '{1902}', 8713, 1, 3, null, 'Beratung ist laut Studie nicht flächendeckend und unterfinanziert; ein Ausbau hilft Betroffenen bei der Durchsetzung, ändert verbreitete Zuschreibungen aber kaum. Wirkungsmessungen fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/forschungsprojekte/EN/Studie_Gut_beraten_en.html', 'offen', '2026-10-10', false, true, 'blind'),
  (8969, 19, 16, 'MV', 'Präventions- und Schutzkonzepte gegen menschenfeindliche Ideologien weiterentwickeln', '{1902}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8970, 19, 16, 'MV', 'Diskriminierungssensible Förderstrukturen in Kunst und Kultur schaffen', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8971, 19, 16, 'ST', 'Landesaktionsprogramm für die Akzeptanz queerer Menschen zusammen mit der Community neu ausgestalten und finanziell ausstatten', '{1903}', 8714, 1, 3, null, 'Fördert Präventions- und Aufklärungsarbeit; eine Übersicht über 418 Experimente findet meist kurze Effekte, Hinweise auf Publikationsverzerrung und unklare Langzeitwirkung. Programme sind oft wenig spezifisch.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8972, 19, 16, 'ST', 'Queere Themen in allen Stationen des Bildungswegs mitbehandeln; Lehrkräfte dafür im Studium bzw. in der Ausbildung befähigen', '{1903}', 8715, 2, 3, null, 'Strukturierte Programme senken Vorurteile bei Kindern und Jugendlichen im Mittel klein bis mittel (d=0,3), am stärksten mit Kontakt und Perspektivübernahme; reine Wissensvermittlung wirkt schwächer, Langzeitbelege fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=25', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8973, 19, 16, 'ST', 'Grundgesetz um das Merkmal der sexuellen und geschlechtlichen Identität erweitern (Bundesratsinitiative)', '{1904}', 8726, 1, 1, null, 'Stärkt den Verfassungsschutz vor staatlicher Diskriminierung, der aber durch Rechtsprechung weitgehend schon besteht; braucht Zweidrittelmehrheiten in Bundestag und Bundesrat, das Land kann nur anstoßen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8974, 19, 16, 'ST', 'Integrationsbudget für Kommunen, u. a. für Willkommensinitiativen, Patenschaftsmodelle und Zuschüsse für Begegnungszentren', '{1902}', 8716, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; vorregistrierte Experimente finden aber kleinere, oft auf die Beteiligten begrenzte Effekte. Die Reichweite einzelner Projekte ist gering.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=97', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8975, 19, 16, 'ST', 'Stigmata im Gesundheitswesen durch Aufklärung vor allem des medizinischen Fachpersonals abbauen', '{1902}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8976, 19, 16, 'ST', 'Beschäftigte im öffentlichen Dienst fortbilden in interkultureller Kompetenz und Sprachkenntnissen', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8977, 19, 16, 'ST', 'Diskriminierende Bezahlkarte durch ein verpflichtendes Basiskonto ersetzen', '{1904}', 8722, 1, 3, null, 'Beseitigt eine staatlich gesetzte Sonderbehandlung im Alltag (Bargeld- und Händlergrenzen), berührt den Rechtsschutz gegen Diskriminierung aber nur am Rand; die Wirkung ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8978, 19, 16, 'ST', 'Verpflichtende KI-Folgenabschätzung vor jedem Einsatz in Landeseinrichtungen, halbjährlich überprüft', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=143', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8979, 19, 17, 'BE', 'Förderung von Nachbarschaftsprojekten, interkulturellen Festen und Sportvereinen, um Vorbehalte zwischen Menschen mit und ohne Migrationshintergrund abzubauen', '{1902}', 8716, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; vorregistrierte Experimente finden aber kleinere, oft auf die Beteiligten begrenzte Effekte. Die Reichweite einzelner Projekte ist gering.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=37', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8980, 19, 17, 'BE', 'Pflichtfach Ethik/Lebenskunde personell stärken und interkulturell sowie werteorientiert ausrichten', '{1902}', null, 1, 2, null, 'Ethikunterricht kann Respekt vor anderen Weltanschauungen fördern, wirkt aber eher allgemein; zusätzliche Lehrkräfte sind knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=37', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8981, 19, 17, 'BE', 'Ansprechstelle der Landesregierung für sexuelle und geschlechtliche Vielfalt wird nicht fortgeführt; Mittel sollen in Projekte gegen homophobe Gewalt fließen', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=33', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8982, 19, 17, 'ST', 'Fortbildungen zur Sensibilisierung in staatlichen Institutionen für den Schutz gleichgeschlechtlicher Ehepaare und anderer Minderheiten', '{1904}', 8709, 1, 3, null, 'Metaanalyse: Trainings verbessern dauerhaft Wissen, Effekte auf Einstellungen und Verhalten lassen aber nach; eingebettet in Organisationsmaßnahmen wirken sie besser. Den Rechtsschutz der Betroffenen ändern sie nicht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8983, 19, 17, 'ST', 'Staatliche und kommunale Einrichtungen sollen keine Konzepte zu Geschlecht, Sexualität oder Identität gegen den Willen der Eltern einführen oder fördern', '{1903}', 8721, 0, 3, null, 'Per Erlass oder Förderrichtlinie umsetzbar, reduziert aber Bildungs- und Akzeptanzarbeit, die Abwertung entgegenwirken soll; ein Beitrag zum Abbau abwertender Einstellungen ist nicht erkennbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=39', null, 'offen', '2026-10-10', false, true, 'blind');

